cat > features/users/api/update-password.ts <<'EOF'
import { useMutation } from '@tanstack/react-query';
import { z } from 'zod';

import { api } from '@/lib/api-client';
import { MutationConfig } from '@/lib/react-query';

export const updatePasswordInputSchema = z
  .object({
    currentPassword: z.string().min(1, 'Required'),
    newPassword: z.string().min(5, 'Must be at least 5 characters'),
    confirmPassword: z.string().min(1, 'Required'),
  })
  .refine((values) => values.newPassword === values.confirmPassword, {
    message: 'Passwords do not match',
    path: ['confirmPassword'],
  });

export type UpdatePasswordInput = z.infer<typeof updatePasswordInputSchema>;

export const updatePassword = ({ data }: { data: UpdatePasswordInput }) => {
  return api.patch(`/users/password`, data);
};

type UseUpdatePasswordOptions = {
  mutationConfig?: MutationConfig<typeof updatePassword>;
};

export const useUpdatePassword = ({
  mutationConfig,
}: UseUpdatePasswordOptions = {}) => {
  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (...args) => {
      onSuccess?.(...args);
    },
    ...restConfig,
    mutationFn: updatePassword,
  });
};
EOF
cat > features/users/components/update-password.tsx <<'EOF'
import { KeyRound } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Form, FormDrawer, Input } from '@/components/ui/form';

import {
  updatePasswordInputSchema,
  useUpdatePassword,
} from '../api/update-password';

export const UpdatePassword = () => {
  const updatePasswordMutation = useUpdatePassword();

  return (
    <FormDrawer
      isDone={updatePasswordMutation.isSuccess}
      triggerButton={
        <Button icon={<KeyRound className="size-4" />} size="sm">
          Change Password
        </Button>
      }
      title="Change Password"
      submitButton={
        <Button
          form="update-password"
          type="submit"
          size="sm"
          isLoading={updatePasswordMutation.isPending}
        >
          Submit
        </Button>
      }
    >
      <Form
        id="update-password"
        onSubmit={(values) => {
          updatePasswordMutation.mutate({ data: values });
        }}
        schema={updatePasswordInputSchema}
      >
        {({ register, formState }) => (
          <>
            <Input
              label="Current Password"
              type="password"
              error={formState.errors['currentPassword']}
              registration={register('currentPassword')}
            />
            <Input
              label="New Password"
              type="password"
              error={formState.errors['newPassword']}
              registration={register('newPassword')}
            />
            <Input
              label="Confirm New Password"
              type="password"
              error={formState.errors['confirmPassword']}
              registration={register('confirmPassword')}
            />
          </>
        )}
      </Form>
    </FormDrawer>
  );
};
EOF
